B.aT8=new A.hc("2000-01-05","\uccab \uc548\uac74: \ub108\ubb34 \ube68\ub9ac \uc815\ud55c \uc77c","\uc544\ub9b0\uc774 \uc790\ub9ac \ubc30\uce58\ub97c 4\ubd84\uc5d0 \ub05d\ub0b8 \uac78 \uc548\uac74\uc73c\ub85c \uc62c\ub838\ub2e4. \uc774\uc11c\uac00 \uc190\uc744 \ub4e4\ub824\ub2e4 \ub9d0\uc558\ub358 \uc774\uc720\ub97c \ub9d0\ud558\uace0, \uc5f4 \uba85\uc740 \ub2e4\uc74c\ubd80\ud130 \uacb0\uc815 \ub4a4\uc5d0 \ud55c \uc0ac\ub78c\uc529 \uc774\ub984\uc744 \ubd88\ub7ec \ud655\uc778\ud558\uae30\ub85c \uc815\ud588\ub2e4.","\uccab \uc548\uac74",B.i6,4286356694,u.u)
B.aTh=new A.hc("2000-01-07","\uac80\uc0b0 \uaddc\uce59\uc774 \uc7a5\ubd80\uc5d0 \ub4e4\uc5b4\uac14\ub2e4","\ud559\uc900\uc774 \uc8fc\ubb38 \uc804 \ucd5c\uc545 \uc190\uc2e4\uc744 \uba3c\uc800 \uc801\ub294 \uce78\uc744 \uc6d0\uc7a5\uc5d0 \ub9cc\ub4e4\uc5c8\ub2e4. \ucc98\uc74c\uc5d4 \ubc88\uac70\ub86d\ub2e4\uace0 \ud588\uc9c0\ub9cc \uadf8 \uce78\uc744 \ube44\uc6b4 \uc0ac\ub78c\uc758 \uc190\uc2e4\uc774 \ub354 \ucef8\ub2e4\ub294 \uac78 \uc544\ubb34\ub3c4 \ubc18\ubc15\ud558\uc9c0 \ubabb\ud588\ub2e4.","\uac80\uc0b0",B.pU,4284317603,u.n)
B.aTg=new A.hc("2000-01-10","\uccab \uc8fc \uc7a5\ubd80 \ub300\uc870","\uc11c\uc544\uac00 \uc5f4 \uad8c\uc758 \uc7a5\ubd80\ub97c \ub098\ub780\ud788 \ub193\uace0 \uccab \uc8fc\ub97c \ub9de\ucdc4\ub2e4. \uc218\uc775\uc774 \uc544\ub2c8\ub77c \uc801\uc9c0 \uc54a\uc740 \uce78\uc774 \uba87 \uac1c\uc778\uc9c0\ub97c \uba3c\uc800 \uc14c\uace0, \ube48 \uce78\uc774 \uac00\uc7a5 \uc801\uc740 \uc0ac\ub78c\uc740 1\ub4f1\uc774 \uc544\ub2c8\uc5c8\ub2e4.","\uc8fc\uac04 \ub300\uc870",B.e6,4293895260,u.u)
B.aTd=new A.hc("2000-01-14","\uc2dc\uacc4 \ub2e4\uc12f \uac1c\uac00 \uac19\uc544\uc84c\ub2e4","\uc9c0\uc548\uc774 \ud2b8\ub808\uc774\ub529 \ud50c\ub85c\uc5b4 \uc2dc\uacc4\ub97c \uc804\ubd80 \ub9de\ucdc4\ub2e4. \uc18c\uc720\uc790 \ud655\uc778\uacfc \uc804\uc6d0 \ucc28\ub2e8, \ub450 \uba85 \uc785\ud68c\uae4c\uc9c0 \uc9c0\ucf1c\uc11c \uc774\ubc88\uc5d0\ub294 \uc544\ubb34\ub3c4 \ub180\ub77c\uc9c0 \uc54a\uc558\ub2e4. \uc21c\uc11c\uac00 \uaddc\uce59\uc774 \ub41c \uccab \uc0ac\ub840\ub85c \uae30\ub85d\ub410\ub2e4.","\uc815\ube44",B.i6,4287605176,"assets/images/cinematic_soft_painted/decimal/bg_decimal_electronics_workshop_2000_v1.png")
B.aTe=new A.hc("2000-01-21","\uc218\uc544\uc758 \uc18c\ubb38 \uacf5\ucc45","\uc218\uc544\uac00 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub290 \ud68c\uc0ac \uc774\ub984\uc744 \uc5b4\ub514\uc11c \ucc98\uc74c \uaebc\ub0b4\ub294\uc9c0 \uc801\uae30 \uc2dc\uc791\ud588\ub2e4. \ucc44\uc544\uac00 \uadf8 \uacf5\ucc45\uc5d0 \uc5b8\uc81c \ub4e4\uc5c8\ub294\uc9c0 \uce78\uc744 \ud558\ub098 \ub354 \uadf8\uc5c8\ub2e4. \uba3c\uc800 \ub4e3\ub294 \uac83\uacfc \uba3c\uc800 \uc544\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4\uace0.","\uc18c\ubb38 \uacf5\ucc45",B.pU,4293233576,u.u)
B.aTl=new A.hc("2000-01-31","\uccab \ub2ec \uacb0\uc0b0","\ud55c\uc11c\uc724\uc774 \uccab \ub2ec \ud658\uc218\uae08\uacfc \uc790\ub9bd\uc801\ub9bd\uae08\uc744 \uac01\uac01 \uc77d\uc5b4 \uc92c\ub2e4. \ubc88 \uc0ac\ub78c\ub3c4 \uc783\uc740 \uc0ac\ub78c\ub3c4 \uc788\uc5c8\uc9c0\ub9cc \ubc25\uacfc \uc7a0\uc790\ub9ac\ub294 \uadf8\ub300\ub85c\uc600\ub2e4. \uacc4\uc57d\uc11c \uccab \uc7a5\uc774 \uc0ac\uc2e4\uc774\ub77c\ub294 \uac8c \ud655\uc778\ub41c \ub0a0.","\uc6d4 \uacb0\uc0b0",B.e6,4294948941,u.u)
